<template><el-table :data="orders" empty-text="暂无项目"><el-table-column type="expand"><template slot-scope="s"><div class="expand-info"><span>目的：{{s.row.purpose||'—'}}</span><span>部位：{{s.row.body_part||'—'}}</span><span v-if="s.row.kind==='DRUG'">医嘱：{{s.row.drug_usage}} / {{s.row.dosage}} / {{s.row.frequency}} / {{s.row.days}}天</span><span>备注：{{s.row.notes||'—'}}</span></div></template></el-table-column><el-table-column prop="item_name" label="项目" min-width="130"/><el-table-column label="类型" width="70"><template slot-scope="s">{{label(s.row.kind)}}</template></el-table-column><el-table-column prop="quantity" label="数量" width="60"/><el-table-column label="金额" width="90"><template slot-scope="s">{{money(s.row.amount_cents)}}</template></el-table-column><el-table-column label="费用" width="95"><template slot-scope="s"><Status :value="s.row.billing_status"/></template></el-table-column><el-table-column label="执行" width="95"><template slot-scope="s"><Status :value="s.row.execution_status" execution/></template></el-table-column><el-table-column v-if="editable" width="75"><template slot-scope="s"><el-button v-if="s.row.kind!=='REG'&&s.row.billing_status==='UNPAID'&&s.row.execution_status==='PENDING'" type="text" @click="$emit('cancel',s.row)">撤销</el-button></template></el-table-column></el-table></template>
<script>import{money,label}from'../api';import Status from'./Status.vue';export default{components:{Status},props:{orders:Array,editable:Boolean},methods:{money,label}};</script>
